namespace RecipeHub.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string Ingredients { get; set; } = "";
    public string Steps { get; set; } = "";
    public List<int> Ratings { get; set; } = new();

    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
}

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
            Steps = "1. Preheat oven to 475°F (245°C).\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes over the dough.\n4. Tear mozzarella and distribute evenly.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and a drizzle of olive oil.",
            Ratings = new List<int> { 5, 4, 5, 4 }
        },
        new Recipe
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = "Spaghetti\nGuanciale (or pancetta)\nEggs\nPecorino Romano\nBlack pepper",
            Steps = "1. Cook spaghetti in salted boiling water.\n2. Crisp guanciale in a pan.\n3. Whisk eggs with grated pecorino and pepper.\n4. Toss hot pasta with guanciale off heat.\n5. Add egg mixture, tossing quickly to create a creamy sauce.\n6. Serve immediately with extra pecorino.",
            Ratings = new List<int> { 5, 5, 4 }
        },
        new Recipe
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nTomato sauce\nHeavy cream\nGarlic\nGinger\nOnion",
            Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and spices, simmer 15 min.\n5. Add cream and cooked chicken.\n6. Simmer 10 more minutes. Serve with rice or naan.",
            Ratings = new List<int> { 5, 4, 5 }
        },
        new Recipe
        {
            Id = 4, Title = "Vegetable Pad Thai", Category = "Thai",
            Ingredients = "Rice noodles\nTofu\nBean sprouts\nGreen onions\nPeanuts\nLime\nTamarind paste\nFish sauce\nSugar\nChili flakes",
            Steps = "1. Soak rice noodles in warm water 20 min.\n2. Press and cube tofu, pan-fry until golden.\n3. Mix tamarind paste, fish sauce, sugar for the sauce.\n4. Stir-fry noodles with sauce until coated.\n5. Add tofu and bean sprouts.\n6. Serve with crushed peanuts, lime, and green onions.",
            Ratings = new List<int> { 4, 4, 5 }
        },
        new Recipe
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa",
            Steps = "1. Brown ground beef in a skillet.\n2. Add taco seasoning and water, simmer 5 min.\n3. Warm tortillas in a dry pan.\n4. Assemble tacos with beef, lettuce, tomato, cheese.\n5. Top with sour cream and salsa.",
            Ratings = new List<int> { 4, 3, 4, 5 }
        },
        new Recipe
        {
            Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts",
            Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract",
            Steps = "1. Preheat oven to 425°F (220°C).\n2. Melt chocolate and butter together.\n3. Whisk eggs, sugar, and vanilla until thick.\n4. Fold chocolate mixture into eggs, then fold in flour.\n5. Pour into greased ramekins.\n6. Bake 12-14 minutes until edges are set but center jiggles.\n7. Invert onto plates and serve immediately.",
            Ratings = new List<int> { 5, 5, 5, 4 }
        }
    };

    private int _nextId = 7;

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe != null && stars >= 1 && stars <= 5)
        {
            recipe.Ratings.Add(stars);
        }
    }

    public void AddRecipe(string title, string category, string ingredients, string steps)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        });
    }
}

